{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Chloramphenicol palmitate, a p-nitrophenyl-containing prodrug, has absolute oral bioavailability of 85±15% in children, supporting high F for p-nitrophenyl small molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A coumarin-containing compound (Z18483535) has human oral bioavailability of 0.5571, supporting high F for coumarin scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Roquinimex, a 4-hydroxy-2-oxoquinoline structurally analogous to the query's 4-hydroxycoumarin core, shows complete oral bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Lercanidipine, a nitrophenyl dihydropyridine, has absolute F ~10% in fed patients, but this is condition-dependent and reflects class-specific first-pass metabolism, so it is only weakly contradictory.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Nimodipine, another nitrophenyl dihydropyridine, has ~13% oral bioavailability due to first-pass metabolism; low transferability to the coumarin query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >=20%): the query is acenocoumarol, a 4-hydroxycoumarin anticoagulant. Supportive evidence from a p-nitrophenyl antibiotic with ~85% absolute F, a coumarin-containing compound with ~56% human F, and a 4-hydroxyquinolinone with complete F outweighs low-F nitrophenyl dihydropyridines whose poor bioavailability is class-specific first-pass metabolism.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for acenocoumarol itself in the provided evidence set.",
    "The most similar evidence molecules have low Morgan scores (<0.31), so structural transfer is indirect.",
    "Low-F analogues (dihydropyridines, organophosphate) have class-specific first-pass metabolism and fed/fasted condition dependence, limiting direct comparison.",
    "Some high-F records involve prodrugs or comparator formulations rather than true IV absolute F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

